<script setup lang="ts">import {computed,ref} from 'vue'; import CustomerForm from '../../components/crm/CustomerForm.vue'; import DetailDrawer from '../../components/common/DetailDrawer.vue'; import DetailFields from '../../components/common/DetailFields.vue'; import {useQuery} from '@tanstack/vue-query'; import {crmRepository} from '../../services/crmRepository'; const keyword=ref(''); const editorOpen=ref(false); const saving=ref(false); const saveError=ref(''); const selected=ref<Record<string,unknown>|null>(null); const detail=ref<Record<string,unknown>|null>(null); const detailLoading=ref(false); const detailError=ref(''); const query=useQuery({queryKey:['crm-customers'],queryFn:()=>crmRepository.customers({page:1,pageSize:100})}); const refresh=()=>{void query.refetch()}; const edit=()=>{if(selected.value){editorOpen.value=true;saveError.value=''}}; const saveCustomer=async(value:Record<string,unknown>)=>{if(!String(value.name||'').trim()){saveError.value='请输入客户名称';return} saving.value=true;saveError.value='';try{await crmRepository.updateCustomer(String(selected.value?.id),value);detail.value=await crmRepository.customer(String(selected.value?.id));editorOpen.value=false;await query.refetch()}catch(e){saveError.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}; const openDetail=async(item:Record<string,unknown>)=>{selected.value=item;detail.value=null;detailLoading.value=true;detailError.value='';try{detail.value=await crmRepository.customer(String(item.id))}catch(e){detailError.value=e instanceof Error?e.message:'客户详情加载失败'}finally{detailLoading.value=false}}; const customers=computed(()=>{const items=query.data.value?.items||[]; const key=keyword.value.trim().toLowerCase(); return key?items.filter(item=>[item.name,item.code,item.contactName].some(value=>String(value||'').toLowerCase().includes(key))):items});</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">CRM CUSTOMERS</span><h2>客户档案</h2></div><button class="secondary" @click="refresh">刷新</button></div><div class="toolbar"><input v-model="keyword" placeholder="搜索客户名称、编码或联系人"/><span>{{customers.length}} 条记录</span></div><div v-if="query.isPending" class="state">正在加载客户档案…</div><div v-else-if="query.isError" class="state error">客户数据加载失败。</div><div v-else-if="!customers.length" class="state">暂无匹配客户。</div><div v-else class="table-wrap"><table><thead><tr><th>客户名称</th><th>客户类型</th><th>等级</th><th>联系人</th><th>联系电话</th><th>更新时间</th></tr></thead><tbody><tr v-for="item in customers" :key="String(item.id)" @click="openDetail(item)"><td><strong>{{item.name}}</strong><small>{{item.code||'暂无编码'}}</small></td><td>{{item.type||'—'}}</td><td><span class="tag">{{item.level||'未分级'}}</span></td><td>{{item.contactName||'—'}}</td><td>{{item.contactPhone||'—'}}</td><td>{{item.createdAt||'—'}}</td></tr></tbody></table></div><DetailDrawer :open="Boolean(selected)" title="客户详情" @close="selected=null"><p v-if="detailLoading" class="state">正在加载客户详情…</p><p v-else-if="detailError" class="state error">{{detailError}}</p><div v-if="saving" class="form-feedback">正在保存…</div><p v-if="saveError" class="form-feedback error">{{saveError}}</p><DetailFields v-else-if="detail" :record="detail" :fields="[{key:'name',label:'客户名称'},{key:'code',label:'客户编码'},{key:'type',label:'客户类型'},{key:'level',label:'客户等级'},{key:'contactName',label:'联系人'},{key:'contactPhone',label:'联系电话'},{key:'address',label:'地址'}]"/></DetailDrawer></section></template>
